import React, { useState, useEffect } from 'react';
import { AlertTriangle, AlertOctagon, Sparkles, X } from 'lucide-react';
import Link from 'next/link';
import { motion, AnimatePresence } from 'framer-motion';

interface QuotaWarningBannerProps {
  status: {
    planType: string;
    usage: { searches: number; pnr: number; live: number };
    limits: { searches: number; pnr: number; live: number };
    warnings: { searches: boolean; pnr: boolean; live: boolean };
  } | null;
  onUpgradeClick?: () => void;
}

export const QuotaWarningBanner = ({ status, onUpgradeClick }: QuotaWarningBannerProps) => {
  const [visible, setVisible] = useState(false);
  const [warnLevel, setWarnLevel] = useState<'none' | 'warning' | 'urgent' | 'exhausted'>('none');
  const [msg, setMsg] = useState('');
  const [usageRatio, setUsageRatio] = useState(0);
  const [featureName, setFeatureName] = useState('');

  useEffect(() => {
    if (!status || !status.usage || !status.limits || !status.warnings) {
      setVisible(false);
      return;
    }

    if (status.planType === 'admin') {
      setVisible(false);
      return;
    }

    // Evaluate which feature is closest to or over depletion limit
    const features: ('searches' | 'pnr' | 'live')[] = ['searches', 'pnr', 'live'];
    let maxRatio = 0;
    let worstFeature: 'searches' | 'pnr' | 'live' | null = null;

    features.forEach(f => {
      const usage = status.usage[f] || 0;
      const limit = status.limits[f] || 1;
      const ratio = usage / limit;
      if (ratio > maxRatio) {
        maxRatio = ratio;
        worstFeature = f;
      }
    });

    if (!worstFeature) {
      setVisible(false);
      return;
    }

    const usageVal = status.usage[worstFeature];
    const limitVal = status.limits[worstFeature];
    const nameMap = { searches: 'search', pnr: 'PNR verification', live: 'live tracking' };
    const name = nameMap[worstFeature];
    setFeatureName(name);
    setUsageRatio(Math.min(maxRatio, 1));

    if (usageVal >= limitVal) {
      setWarnLevel('exhausted');
      setMsg(`You have exhausted your free daily ${name} limits. Upgrade now to Blitz PRO for unlimited access!`);
      setVisible(true);
    } else if (maxRatio >= 0.95) {
      setWarnLevel('urgent');
      setMsg(`Critical: You have used ${usageVal}/${limitVal} of your free daily ${name}s. Watch an ad or upgrade to keep tracking.`);
      setVisible(true);
    } else if (maxRatio >= 0.90) {
      setWarnLevel('urgent');
      setMsg(`Warning: You have used ${usageVal}/${limitVal} of your free daily ${name}s. Upgrade to Blitz PRO for uninterrupted access.`);
      setVisible(true);
    } else if (maxRatio >= 0.80) {
      setWarnLevel('warning');
      setMsg(`Notice: You have used ${usageVal}/${limitVal} of your free daily ${name}s.`);
      setVisible(true);
    } else {
      setVisible(false);
    }
  }, [status]);

  const bgStyles = {
    none: '',
    warning: 'bg-yellow-500/10 border-yellow-500/30 text-yellow-800 dark:text-yellow-200',
    urgent: 'bg-orange-500/15 border-orange-500/40 text-orange-800 dark:text-orange-200',
    exhausted: 'bg-red-500/20 border-red-500/50 text-red-800 dark:text-red-200',
  };

  const barColor = {
    none: 'bg-slate-400',
    warning: 'bg-yellow-400',
    urgent: 'bg-orange-400',
    exhausted: 'bg-red-500',
  };

  const iconColor = {
    none: '',
    warning: 'text-yellow-400',
    urgent: 'text-orange-400',
    exhausted: 'text-red-500',
  };

  return (
    <AnimatePresence>
      {visible && (
        <motion.div
          key="quota-banner"
          initial={{ opacity: 0, y: -12, scale: 0.98 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          exit={{ opacity: 0, y: -8, scale: 0.97 }}
          transition={{ type: 'spring' as const, stiffness: 300, damping: 24 }}
          className={`w-full border rounded-2xl p-4 shadow-lg ${bgStyles[warnLevel]}`}
        >
          {/* Usage progress bar */}
          <div className="w-full h-1 bg-black/10 rounded-full mb-3 overflow-hidden">
            <motion.div
              className={`h-full rounded-full ${barColor[warnLevel]}`}
              initial={{ width: 0 }}
              animate={{ width: `${usageRatio * 100}%` }}
              transition={{ duration: 0.8, ease: 'easeOut' as const, delay: 0.2 }}
            />
          </div>

          <div className="flex flex-col md:flex-row items-center justify-between gap-4">
            <div className="flex items-center gap-3 text-left">
              {warnLevel === 'exhausted' ? (
                <motion.div
                  animate={{ scale: [1, 1.1, 1] }}
                  transition={{ repeat: Infinity, duration: 1.8, ease: 'easeInOut' as const }}
                >
                  <AlertOctagon className={`w-5 h-5 flex-shrink-0 ${iconColor[warnLevel]}`} />
                </motion.div>
              ) : (
                <AlertTriangle className={`w-5 h-5 flex-shrink-0 ${iconColor[warnLevel]}`} />
              )}
              <p className="text-sm font-semibold tracking-wide leading-relaxed">{msg}</p>
            </div>

            <div className="flex items-center gap-3 w-full md:w-auto justify-end">
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={onUpgradeClick}
                className="px-4 py-2 text-xs font-black tracking-widest uppercase bg-blue-600 hover:bg-blue-700 text-white rounded-xl shadow-md transition-all flex items-center gap-1.5 whitespace-nowrap"
              >
                <Sparkles className="w-3.5 h-3.5" /> Upgrade
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => setVisible(false)}
                className="p-1.5 rounded-full hover:bg-card/85 text-muted hover:text-main transition-colors"
                aria-label="Dismiss"
              >
                <X className="w-4 h-4" />
              </motion.button>
            </div>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
};
